"""Gera as páginas estáticas; não é necessário Python para usar o sistema."""
from pathlib import Path
ROOT = Path(__file__).resolve().parent.parent
def field(label, id, type='text', extra='', name=None):
    return f'<label class="form-label" for="{id}">{label}</label><input class="form-control" id="{id}" type="{type}" {extra} '+(f'name="{name}"' if name else '')+'>'
def select(label,id,content='',extra=''):
    return f'<label class="form-label" for="{id}">{label}</label><select class="form-select" id="{id}" {extra}>{content}</select>'
def button(text,id='',type='button'):
    return f'<button class="btn btn-primary mt-3" type="{type}" '+(f'id="{id}"' if id else '')+f'>{text}</button>'
def modal(id,title,body,form=None):
    return f'<div class="modal fade" id="{id}" tabindex="-1" aria-labelledby="{id}-title" aria-hidden="true"><div class="modal-dialog modal-lg modal-dialog-centered"><div class="modal-content"><div class="modal-header"><h2 class="modal-title fs-5" id="{id}-title">{title}</h2><button class="btn-close" data-bs-dismiss="modal" aria-label="Fechar"></button></div><div class="modal-body">'+(f'<form id="{form}">{body}<div class="text-end">{button("Salvar",type="submit")}</div></form>' if form else body)+'</div></div></div></div>'
def tabs(items):
    nav='<ul class="nav nav-tabs" role="tablist">'+''.join(f'<li class="nav-item" role="presentation"><button class="nav-link {"active" if i==0 else ""}" id="{id}-tab" data-bs-toggle="tab" data-bs-target="#{id}" type="button" role="tab" aria-controls="{id}" aria-selected="{str(i==0).lower()}">{title}</button></li>' for i,(id,title,body) in enumerate(items))+'</ul>'
    return nav+'<div class="tab-content">'+''.join(f'<section class="tab-pane fade {"show active" if i==0 else ""}" id="{id}" role="tabpanel" aria-labelledby="{id}-tab">{body}</section>' for i,(id,title,body) in enumerate(items))+'</div>'
def page(file,title,subtitle,body,module,login=False):
    html=f'''<!doctype html>
<html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{title} · Ateliê Gestão</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css" rel="stylesheet"><link href="css/style.css" rel="stylesheet"></head>
<body>{'' if login else '<header id="nav"></header>'}<main class="container"><div class="{'login panel' if login else ''}"><p class="eyebrow">Ateliê Gestão / seu salão, organizado</p><h1>{title}</h1><p class="subtitle">{subtitle}</p><div id="notice" class="d-none" role="alert" aria-live="polite"></div>{body}</div></main><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script><script src="https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2"></script><script type="module" src="js/{module}.js"></script></body></html>'''
    (ROOT/file).write_text(html,encoding='utf-8')
page('login.html','Bem-vinda ao Ateliê','Entre para cuidar da rotina do seu salão.', '<form id="login">'+field('E-mail','email','email','required autocomplete="username"')+field('Senha','password','password','required autocomplete="current-password"')+button('Entrar',type='submit')+'</form>','auth',True)
page('index.html','Um olhar sobre o seu dia','Agenda, resultados e estoque em um só lugar.', '<div class="row g-4 mb-4">'+''.join(f'<div class="col-md-4"><article class="card"><span><i class="bi bi-{icon} me-2"></i>{label}</span><strong class="metric" id="{id}">—</strong></article></div>' for label,id,icon in [('Faturamento do dia','revenue','cash-coin'),('Atendimentos hoje','appointments','calendar-check'),('Produtos com estoque baixo','low','box-seam')])+'</div><div class="row g-4"><section class="col-lg-8"><div class="panel"><h2 class="fs-5">Agenda de hoje</h2><div id="schedule"></div><a href="agendamentos.html">Ver agenda completa →</a></div></section><section class="col-lg-4"><div class="panel"><h2 class="fs-5">Atenção ao estoque</h2><div id="stock"></div></div></section></div>','dashboard')
page('clientes.html','Clientes','Relações que fazem o salão crescer.', '<div class="d-flex gap-3 align-items-center mb-4"><input id="search" class="form-control" placeholder="Buscar por nome ou telefone" aria-label="Buscar clientes">'+button('Nova cliente','new')+'</div><section class="panel" id="list"></section>'+modal('client-modal','Cadastro de cliente','<input type="hidden" id="client-id">'+field('Nome','name',extra='required maxlength="150"')+field('Telefone / WhatsApp com DDD','phone','tel','required maxlength="25"')+field('Data de nascimento','birth','date'),'client-form')+modal('history-modal','Histórico de visitas','<div id="history"></div>'),'clientes')
service_fields='<input type="hidden" id="service-id">'+field('Título','title',extra='required',name='title')+field('Descrição','service-description',name='description')+field('Preço (R$)','price','number','required min="0" step="0.01"','price')+field('Duração (minutos)','duration','number','required min="1" step="1"','duration_minutes')+'<label class="d-block mt-3"><input type="checkbox" id="is_active" name="is_active" checked> Serviço ativo</label>'
product_fields='<input type="hidden" id="product-id">'+field('Nome','product-name',extra='required',name='name')+field('Categoria','category',name='category')+field('Preço de custo (R$)','cost','number','required min="0" step="0.01"','cost_price')+field('Preço de venda (R$)','sale-price','number','required min="0" step="0.01"','sale_price')+field('Estoque mínimo','minimum','number','required min="0" step="1"','min_stock_level')+'<p class="text-secondary mt-3">Produtos novos começam com estoque zero. Use Ajustar estoque para registrar a entrada inicial.</p><label><input type="checkbox" id="internal" name="is_internal_use_only"> Uso interno exclusivo</label>'
page('servicos-produtos.html','Serviços e estoque','Seu catálogo e seus insumos sob controle.',tabs([('services','Serviços',button('Novo serviço','new-service')+'<div id="services-list" class="panel mt-3"></div>'),('products','Produtos e insumos',button('Novo produto','new-product')+'<div id="products-list" class="panel mt-3"></div>')])+modal('service-modal','Serviço',service_fields,'service-form')+modal('product-modal','Produto',product_fields,'product-form')+modal('stock-modal','Ajustar estoque','<input type="hidden" id="stock-id">'+field('Variação em unidades (negativo para baixa)','delta','number','required step="1"')+'<p class="text-secondary mt-2">Exemplo: −2 para consumo de insumo; 10 para entrada de mercadoria.</p>','stock-form'),'servicos-produtos')
page('agendamentos.html','Agenda','Planeje cada atendimento com tranquilidade.', '<div class="row align-items-end g-3 mb-4"><div class="col-md-4">'+field('Data','day','date','required')+'</div><div class="col-md-5">'+select('Profissional','professional-filter')+'</div><div class="col-md-3">'+button('Novo agendamento','new')+'</div></div><section id="list" class="panel"></section>'+modal('appointment-modal','Novo agendamento',select('Cliente','client-id',extra='required')+select('Profissional','professional-id',extra='required')+field('Início','start','datetime-local','required')+select('Serviços (Ctrl/Cmd para selecionar vários)','service-ids',extra='multiple required')+'<p id="estimate" class="alert alert-light mt-3"></p>','appointment-form')+modal('finish-modal','Concluir atendimento','<input type="hidden" id="finish-id"><p id="finish-summary"></p><p>A confirmação registra a receita, calcula a comissão e conclui o atendimento.</p>','finish-form'),'agendamentos')
cash='<form id="filter" class="row g-3 align-items-end"><div class="col-md-4">'+field('De','from','date','required')+'</div><div class="col-md-4">'+field('Até','to','date','required')+'</div><div class="col-md-4">'+button('Filtrar',type='submit')+'</div></form><p class="mt-4">Saldo no período: <strong id="balance">—</strong></p><div id="cash-list" class="panel"></div><form id="transaction-form" class="panel mt-4"><h2 class="fs-5">Registrar movimentação operacional</h2>'+select('Tipo','type','<option value="receita">Receita</option><option value="despesa">Despesa</option>')+field('Descrição','description',extra='required')+field('Valor (R$)','amount','number','required min="0.01" step="0.01"')+button('Registrar',type='submit')+'</form>'
sale='<form id="sale-form" class="panel">'+select('Cliente (opcional)','sale-client')+'<div class="row"><div class="col-md-8">'+select('Produto','product')+'</div><div class="col-md-4">'+field('Quantidade','quantity','number','min="1" step="1" value="1"')+'</div></div>'+button('Adicionar produto','add-product')+'<div id="cart" class="mt-4"></div><p>Total: <strong id="sale-total"></strong></p>'+button('Finalizar venda',type='submit')+'</form>'
page('financeiro.html','Financeiro','Clareza para acompanhar os resultados do salão.',tabs([('cash','Caixa',cash),('sale','Venda de balcão',sale),('commissions','Comissões','<p>Comissões de todos os períodos.</p><div id="commission-list" class="panel"></div>')]),'financeiro')
